before:
```swift
enum Door {
    case open
    case closed
}
func sign(_ door: Door) -> String {
    switch door {
    case .open: return "Come in"
    case .closed: return "Please wait"
    }
}
print(sign(.closed))
```
This prints Please wait. Changing the argument to .open selects the other branch.

```swift
enum Download {
    case idle
    case receiving(bytes: Int)
}
func description(_ download: Download) -> String {
    switch download {
    case .idle: return "Not started"
    case .receiving(let bytes): return "Received \(bytes) bytes"
    }
}
print(description(.receiving(bytes: 24)))
```
The let bytes pattern reads the number carried by receiving. It does not create a new download.

after:
```swift
enum Download {
    case idle
    case receiving(bytes: Int)
}
func description(_ download: Download) -> String {
    switch download {
    case .idle: return "Not started"
    case .receiving(let bytes): return "Received \(bytes) bytes"
    }
}
print(description(.receiving(bytes: 24)))
```
This prints Received 24 bytes. A byte is a small unit of computer data. The download is receiving, and it carries the number 24.
